    private void Preferences()
    {
        var p=Card("Menu rapide", "Un clic sur l’icône Jerry dans la zone de notification ouvre les commandes. Choisissez les outils à y afficher.");
        foreach(var key in S.TrayItems.Keys.ToArray()) { var item=key; Check(p,HotkeyLabel(item),S.TrayItems[item],v=>S.TrayItems[item]=v); }
        p.Children.Add(Action("Ouvrir le menu rapide",controller.ShowQuickMenu));
        p=Card("Réglages");
        p.Children.Add(Action("Réinitialiser les réglages…",()=>{if(MessageBox.Show(this,"Restaurer les réglages de Jerry et effacer les raccourcis personnalisés ?","Réinitialiser Jerry",MessageBoxButton.YesNo,MessageBoxImage.Question)==MessageBoxResult.Yes){controller.ResetSettings();ReloadPage();}}));
        p.Children.Add(Action("Quitter Jerry",controller.Quit));
    }
